/**
 * Procedural block textures. Every pixel of every tile is generated by code, deterministically
 * (seeds come from the tile name through core/rng.ts hashes; Math.random is never used).
 *
 * Tile layer order = TILE_NAMES order (src/blocks/registry.ts, populated by blocks/defs.ts).
 * Pixel format: TILE_SIZE x TILE_SIZE RGBA8, row 0 = TOP row of the image.
 */
import '../blocks/defs'; // side effect: registers every block, filling TILE_NAMES
import { TILE_NAMES } from '../blocks/registry';
import { TILE_SIZE } from '../core/constants';
import type { TileTextureData } from '../render/backend';
import { bleedTransparent, Canvas } from './canvas';
import { BUILD_PAINTERS } from './paint/build';
import { FLUID_PAINTERS } from './paint/fluid';
import { seedOf, type Painter } from './paint/kit';
import { MACHINE_PAINTERS } from './paint/machine';
import { OVERLAY_PAINTERS } from './paint/overlay';
import { PLANT_PAINTERS } from './paint/plants';
import { TERRAIN_PAINTERS } from './paint/terrain';
import { WOOD_PAINTERS } from './paint/wood';

const PAINTERS: ReadonlyMap<string, Painter> = new Map(
  Object.entries({
    ...TERRAIN_PAINTERS,
    ...WOOD_PAINTERS,
    ...BUILD_PAINTERS,
    ...FLUID_PAINTERS,
    ...MACHINE_PAINTERS,
    ...PLANT_PAINTERS,
    ...OVERLAY_PAINTERS,
  }),
);

/**
 * How a tile uses its alpha channel:
 *  - opaque      : alpha 255 everywhere
 *  - cutout      : alpha strictly 0 or 255 (alpha-tested)
 *  - translucent : partial alpha (water ~150-175, ice 200, glue overlay ~140, cracks 0/200)
 */
export type TileAlphaMode = 'opaque' | 'cutout' | 'translucent';

const CUTOUT = new Set([
  'leaves_oak',
  'leaves_pine',
  'glass',
  'helm_wheel',
  'propeller_blade',
  'torch',
  'flower_red',
  'flower_yellow',
  'tall_grass',
  'item_glue',
  'item_bucket',
  'item_bucket_water',
  'item_bucket_lava',
]);
const TRANSLUCENT = new Set(['water_still', 'water_flow', 'ice', 'glue_face', ...Array.from({ length: 8 }, (_, k) => `crack_${k}`)]);

/** Alpha usage of a tile (see TileAlphaMode). Throws on an unknown name. */
export function tileAlphaMode(name: string): TileAlphaMode {
  if (!PAINTERS.has(name)) throw new Error(`unknown tile '${name}'`);
  return CUTOUT.has(name) ? 'cutout' : TRANSLUCENT.has(name) ? 'translucent' : 'opaque';
}

/** True when a painter exists for the tile name. */
export function hasTilePainter(name: string): boolean {
  return PAINTERS.has(name);
}

/** Every tile name this module can paint (a superset check for TILE_NAMES). */
export function paintableTileNames(): string[] {
  return [...PAINTERS.keys()];
}

/**
 * Paints one tile: TILE_SIZE*TILE_SIZE*4 RGBA bytes, row 0 = top. Returns a fresh array on
 * every call (callers may mutate it). Throws on an unknown name.
 */
export function paintTile(name: string): Uint8Array {
  const painter = PAINTERS.get(name);
  if (!painter) throw new Error(`unknown tile '${name}'`);
  const c = new Canvas(TILE_SIZE);
  painter(c, seedOf(name));
  const mode = CUTOUT.has(name) ? 'cutout' : TRANSLUCENT.has(name) ? 'translucent' : 'opaque';
  const d = c.data;
  // Enforce the alpha contract regardless of painter details: the renderer relies on it.
  if (mode === 'opaque') {
    for (let i = 3; i < d.length; i += 4) d[i] = 255;
  } else if (mode === 'cutout') {
    for (let i = 3; i < d.length; i += 4) d[i] = d[i]! >= 128 ? 255 : 0;
  }
  if (mode !== 'opaque') bleedTransparent(c);
  return d;
}

/** Every TILE_NAMES entry, in order, as one texture-array upload. */
export function paintAllTiles(): TileTextureData {
  const layer = TILE_SIZE * TILE_SIZE * 4;
  const names = TILE_NAMES;
  const pixels = new Uint8Array(layer * names.length);
  for (let i = 0; i < names.length; i++) pixels.set(paintTile(names[i]!), i * layer);
  return { size: TILE_SIZE, count: names.length, pixels };
}
